<script setup>
import {useDashboard} from '../../composables/useDashboard';
const {deliveryStart,deliveryEnd,deliveryOrderQuery,flowSupplierQuery,flowBuyerQuery,flowOrderRows}=useDashboard();
</script>
<template>
<section class="page-stack"><div class="query-panel flow-query"><label>订单编号<input v-model="deliveryOrderQuery" placeholder="请输入订单编号"></label><label>供应商<input v-model="flowSupplierQuery" placeholder="请输入供应商名称"></label><label>采购员<input v-model="flowBuyerQuery" placeholder="请输入采购员"></label><label>开始日期<input type="date" v-model="deliveryStart"></label><label>结束日期<input type="date" v-model="deliveryEnd"></label><button>查询</button></div><article class="data-box order-detail-table"><header>订单明细查询</header><div><table><thead><tr><th v-for="h in ['订单号','采购员','供应商名称','物料名称','订单数量','供应商确认数量','已发货数量','预计到货日期','状态']">{{h}}</th><th class="order-progress-heading"><span>订单进度</span><div class="order-progress-labels"><span v-for="step in ['请购','下单','确认','送货','到货检验','入库']" :key="step">{{step}}</span></div></th></tr></thead><tbody><tr v-for="x in flowOrderRows" :key="x.orderId"><td>{{x.orderId}}</td><td>{{x.buyer}}</td><td>{{x.supplier}}</td><td>{{x.material}}</td><td>{{x.quantity}}</td><td>{{x.confirmed}}</td><td>{{x.shipped}}</td><td>{{x.expected}}</td><td><span :class="['flow-status',x.status]">{{x.status}}</span></td><td><div class="order-progress"><i v-for="(done,i) in x.progress" :key="i" :class="{done}"></i></div></td></tr><tr v-if="!flowOrderRows.length"><td colspan="10" class="empty-cell">暂无符合条件的订单</td></tr></tbody></table></div></article></section>
